const today = new Date();
const day = today.getDate();
const MY_TEAM = "한화";

// 문자열로 온 data를 JSON으로 파싱
const raw = $input.first().json.data;
const parsed = JSON.parse(raw);
const rows = parsed.rows;

// 오늘 날짜 row 찾기
let todayGame = null;
for (const week of rows) {
  for (const game of week.row) {
    const dayMatch = game.Text?.match(/<li class="dayNum">(\d+)<\/li>/);
    if (dayMatch && parseInt(dayMatch[1]) === day) {
      todayGame = game;
      break;
    }
  }
  if (todayGame) break;
}

if (!todayGame) {
  return [{ json: { hasGame: false, reason: "오늘 날짜 없음" } }];
}

const text = todayGame.Text;
const cls = todayGame.Class;

// ── 경기 종료 (endGame) ──
if (cls === 'endGame') {
  const homeMatch = text.match(new RegExp(`<li>${MY_TEAM} <b>(\\d+) : (\\d+)<\\/b> (\\S+)`));
  const awayMatch = text.match(new RegExp(`<li>(\\S+) <b>(\\d+) : (\\d+)<\\/b> ${MY_TEAM}`));

  if (!homeMatch && !awayMatch) {
    return [{ json: { hasGame: false, reason: "우리팀 경기 없음 (종료)" } }];
  }

  const isHome = !!awayMatch;  
  const myScore  = isHome ? parseInt(homeMatch[1]) : parseInt(awayMatch[3]);
  const oppScore = isHome ? parseInt(homeMatch[2]) : parseInt(awayMatch[2]);
  const opponent = isHome ? homeMatch[3] : awayMatch[1];
  const result   = myScore > oppScore ? "승" : myScore < oppScore ? "패" : "무";

  return [{ json: { hasGame: true, status: "종료", result, myScore, oppScore, opponent, isHome } }];
}

// ── 오늘/예정 경기 (todayGame / "") ──
const homeMatch = text.match(new RegExp(`<li>${MY_TEAM} : (\\S+) \\[(.+?)\\]<\\/li>`));
const awayMatch = text.match(new RegExp(`<li>(\\S+) : ${MY_TEAM} \\[(.+?)\\]<\\/li>`));

if (!homeMatch && !awayMatch) {
  return [{ json: { hasGame: false, reason: "우리팀 경기 없음 (예정)" } }];
}

const isHome   = !!awayMatch;
const opponent = isHome ? awayMatch[1] : homeMatch[1];
const stadium  = isHome ? awayMatch[2] : homeMatch[2];

// 요일로 경기 시작 시간 결정
const dayOfWeek = today.getDay(); // 0=일, 1=월 ... 6=토
const isWeekend = (dayOfWeek === 0 || dayOfWeek === 6);

const gameHour   = isWeekend ? 14 : 18;
const gameMinute = isWeekend ? 0  : 30;

// 폴링 시작 = 경기 3시간 전
const pollStart = new Date(today);
pollStart.setHours(gameHour - 3, gameMinute, 0, 0);

return [{ json: {
  hasGame: true,
  status: "예정",
  result: null,
  opponent,
  stadium,
  isHome,
  day,
  gameHour,
  gameMinute,
  pollStartHour:   pollStart.getHours(),
  pollStartMinute: pollStart.getMinutes(),
}}];
